      ]
    },
    {
      "field": "remedy",
      "quote": "Confirm performer casting age and animal handling plans; if a minor performer or live animal is cast, enforce jurisdictional minor working hours and welfare safeguards, provide certified animal handler supervision per CSATF Safety Bulletin #6, or stage the child and animal elements separately from night water and pyrotechnic filming via plates/split-screen.",
      "basis": "planning",
